data class Download(val id: Long, val done: Boolean, val bytes: Long)

val downloads = mutableListOf(Download(1, true, 10), Download(2, false, 0))

// ❌ the iterator sees modCount change under it
for (d in downloads) if (d.done) downloads.remove(d)
downloads.forEach { if (it.done) downloads.remove(it) }   // same iterator, same crash

// ✅ says what you mean, one pass, removal goes through the iterator
downloads.removeAll { it.done }
downloads.retainAll { it.bytes > 0 }

// ✅ a fresh list when the state holder wants a new value anyway
_state.update { it.copy(items = it.items.filterNot(Download::done)) }

// ✅ explicit iterator when the pass does more than remove
val iter = downloads.iterator()
while (iter.hasNext()) {
  val d = iter.next()
  if (d.done) {
    cache.evict(d.id)
    iter.remove()
  }
}

// ✅ iterate a snapshot when the body may mutate the list indirectly
for (d in downloads.toList()) listeners.forEach { it.onSeen(d) }

// the silent variant: removing the second-to-last element skips the last one
val nums = mutableListOf(1, 2, 3, 4)
for (n in nums) if (n == 3) nums.remove(n)   // no crash, and 4 is never visited

data class Order(val id: Long, val customerId: Long, val updatedAt: Instant, val total: Int)

// ❌ silently keeps one order per customer — whichever came last in list order
val byCustomer: Map<Long, Order> = orders.associateBy { it.customerId }

// ✅ the key is not unique, so keep every value
val ordersByCustomer: Map<Long, List<Order>> = orders.groupBy { it.customerId }

// ...and choose the survivor on purpose
val latestByCustomer: Map<Long, Order> =
  ordersByCustomer.mapValues { (_, list) -> list.maxBy(Order::updatedAt) }

// ✅ associateBy is correct when the key really is unique
val byId: Map<Long, Order> = orders.associateBy(Order::id)

// last wins, so sort ASCENDING by the deciding field to keep the newest
val newestWins = orders.sortedBy(Order::updatedAt).associateBy { it.customerId }

// distinctBy keeps the FIRST match, associateBy keeps the LAST
val firstPerCustomer: List<Order> = orders.distinctBy { it.customerId }

// a cheap guard where the invariant matters
check(orders.distinctBy(Order::id).size == orders.size) { "duplicate order ids in page" }

// only counting? no intermediate lists at all
val ordersPerCustomer: Map<Long, Int> = orders.groupingBy { it.customerId }.eachCount()

class FeedFragment : Fragment() {
