  private val viewModel: FeedViewModel by viewModels()

  // ❌ inner: a hidden this@FeedFragment field keeps the whole view tree alive
  inner class LeakyListener : EventBus.Listener {
    override fun onEvent(e: Event) { binding?.title?.text = e.title }
  }

  // ✅ nested: no outer reference, dependencies are explicit
  class TitleListener(private val sink: MutableStateFlow<String>) : EventBus.Listener {
    override fun onEvent(e: Event) { sink.value = e.title }
  }

  private val listener = TitleListener(viewModel.title)

  override fun onStart() { EventBus.register(listener) }
  override fun onStop() { EventBus.unregister(listener) }   // ownership is still yours
}

