// ✅ one pass, keys in reading order
val once = tasks.sortedWith(compareBy({ it.due }, { it.title }))

// mixed directions need the builder form
val board = tasks.sortedWith(
  compareByDescending<Task> { it.priority }.thenBy { it.due }.thenBy { it.title }
)

// nullable key: vararg compareBy puts null FIRST — be explicit instead
val byOwner = tasks.sortedWith(compareBy(nullsLast(naturalOrder<String>())) { it.owner })

// new list vs in place
