val mutable = tasks.toMutableList()
mutable.sortBy { it.due }                   // mutates the receiver

// the selector runs on every comparison — precompute an expensive key
val byParsed = tasks
  .map { it to LocalDate.parse(it.title.substringAfter('@')) }
  .sortedBy { (_, date) -> date }
  .map { (task, _) -> task }

