// entity: identity is the id, and only the id
class User(val id: Long, var displayName: String) {
  override fun equals(other: Any?): Boolean {
    if (this === other) return true                       // cheap fast path
    if (other == null || javaClass != other.javaClass) return false
    return id == (other as User).id                       // not displayName: it is mutable
  }
  override fun hashCode(): Int = id.hashCode()            // same field as equals
  override fun toString(): String = "User(id=$id)"
}

// value: every field participates, and the hash mixes them
class Point(val x: Int, val y: Int) {
  override fun equals(other: Any?) = other is Point && x == other.x && y == other.y
  override fun hashCode() = 31 * x + y
}

// ❌ arrays compare by reference — this holds inside a data class too
data class Payload(val bytes: ByteArray)
val same = Payload(byteArrayOf(1)) == Payload(byteArrayOf(1))   // false

// ✅ an array field needs content comparison
class Blob(val bytes: ByteArray) {
  override fun equals(other: Any?) = other is Blob && bytes.contentEquals(other.bytes)
  override fun hashCode() = bytes.contentHashCode()
}

